<script lang="ts">
  import { onMount } from 'svelte';
  import { page } from '$app/stores';
  import { goto } from '$app/navigation';
  import { api, metricCatalog, SYSTEM_METRIC_NAMES } from '$lib/api/client';
  import type { CollectorHealth, Entity, FleetSummary, MetricCatalogEntry, MetricSeries } from '$lib/types/api';
  import StatusMark from '$lib/components/StatusMark.svelte';
  import StatePanel from '$lib/components/StatePanel.svelte';
  import MetricChart from '$lib/components/MetricChart.svelte';
  import { parseDashboardState } from '$lib/state/url';
  import { formatMetric, formatTime, isStale } from '$lib/utils/format';

  let summary: FleetSummary | undefined;
  let allEntities: Entity[] = [];
  let hosts: Entity[] = [];
  let reports: CollectorHealth[] = [];
  let catalog: MetricCatalogEntry[] = [];
  let telemetry: Record<string, MetricSeries[]> = {};
  let loading = true;
  let refreshing = false;
  let error = '';
  let refreshTimer: ReturnType<typeof setInterval> | undefined;
  let resourceQuery = '';
  let showHistorical = false;
  $: range = parseDashboardState($page.url);
  $: chartRange = $page.url.searchParams.has('start') || $page.url.searchParams.has('end') ? range : { start: new Date(range.end.getTime() - 60 * 60 * 1000), end: range.end };
  $: selectedId = $page.url.searchParams.get('host') || hosts[0]?.id || '';
  $: view = $page.url.searchParams.get('view') || 'overview';
  $: selectedHost = hosts.find(host => host.id === selectedId) || hosts[0];
  $: selectedMetrics = selectedHost ? (telemetry[selectedHost.id] || []) : [];
  $: selectedGroups = groupMetrics(selectedMetrics);
  $: topNodes = [...hosts].sort((a, b) => Number(b.active) - Number(a.active) || Date.parse(b.last_seen) - Date.parse(a.last_seen)).slice(0, 3);

  async function load() {
    if (summary) refreshing = true; else loading = true; error = '';
    try {
      const [nextSummary, nextEntities, nextReports, nextCatalog] = await Promise.all([api.fleet(), api.entities(), api.collectors(), metricCatalog()]);
      summary = nextSummary; allEntities = nextEntities; hosts = nextEntities.filter(entity => entity.kind === 'host'); reports = nextReports; catalog = nextCatalog;
      if (view !== 'topology') {
        const pairs = await Promise.all(hosts.map(async host => [host.id, await api.metrics(host.id, chartRange.start.toISOString(), chartRange.end.toISOString(), 180, undefined, SYSTEM_METRIC_NAMES, 'host')] as const));
        telemetry = Object.fromEntries(pairs);
      }
    } catch (e) { error = e instanceof Error ? e.message : 'Unable to read fleet telemetry'; }
    finally { loading = false; refreshing = false; }
  }
  function groupMetrics(items: MetricSeries[]) {
    const result: Record<string, MetricSeries[]> = { cpu: [], memory: [], network: [], disk: [] };
    for (const item of items) {
      const group = item.name.startsWith('system.cpu') || item.name.startsWith('system.load') ? 'cpu' : item.name.startsWith('system.memory') ? 'memory' : item.name.startsWith('system.network') ? 'network' : item.name.startsWith('system.disk') ? 'disk' : '';
      if (group && result[group].length < 8) result[group].push(item);
    }
    return result;
  }
  function metricValue(items: MetricSeries[], name: string, mode: 'last' | 'sum' = 'last') {
    const values = items.filter(item => item.name === name).map(item => item.buckets.at(-1)?.last).filter((value): value is number => value != null && Number.isFinite(value));
    return values.length ? (mode === 'sum' ? values.reduce((sum, value) => sum + value, 0) : values[0]) : null;
  }
  function bytes(value: number | null) { return value == null ? '—' : formatMetric(value, 'bytes'); }
  function rate(value: number | null) { return value == null ? '—' : value < 1024 ? `${value.toFixed(0)} B/s` : `${formatMetric(value, 'bytes')}/s`; }
  function testAgent(host: Entity) { return /test|demo|fixture|sample/i.test(`${host.name} ${JSON.stringify(host.labels || {})}`); }
  function reportFor(host: Entity) { return reports.find(report => report.agent_id === host.agent_id) || reports.find(report => report.agent_id === host.id); }
  function hostProcesses(host: Entity) { return allEntities.filter(item => item.kind === 'process' && item.host_id === host.id); }
  function hostServices(host: Entity) { return allEntities.filter(item => item.kind === 'service' && item.host_id === host.id); }
  function hostDependencies(host: Entity) { return allEntities.filter(item => item.kind === 'dependency' && item.host_id === host.id); }
  function hostContainers(host: Entity) { return allEntities.filter(item => item.kind === 'container' && item.host_id === host.id); }
  function serviceProcesses(service: Entity) { return allEntities.filter(item => item.kind === 'process' && item.parent_id === service.id); }
  function serviceDependencies(service: Entity) { return allEntities.filter(item => item.kind === 'dependency' && item.related_ids?.includes(service.id)); }
  function unassignedProcesses(host: Entity) { return hostProcesses(host).filter(item => !item.parent_id); }
  function matchesResource(item: Entity) { const query = resourceQuery.trim().toLowerCase(); return !query || `${item.name} ${item.command || ''} ${item.pid || ''}`.toLowerCase().includes(query); }
  function visibleResources(items: Entity[]) { return items.filter(item => (showHistorical || item.active) && matchesResource(item)); }
  function activeCount(items: Entity[]) { return items.filter(item => item.active).length; }
  function setHost(id: string) { goto(`/?host=${encodeURIComponent(id)}`, { replaceState: true, keepFocus: true, noScroll: true }); }
  onMount(() => { load(); refreshTimer = setInterval(load, 15000); return () => { if (refreshTimer) clearInterval(refreshTimer); }; });
</script>

<div class="page-heading"><div><span class="eyebrow">Operations / control plane</span><h1 class="display">Fleet recorder</h1><p>One view of every enrolled agent, host and signal being recorded.</p></div><div class="heading-actions"><span class="freshness mono">{summary ? `UPDATED ${formatTime(new Date())}` : 'CONNECTING'}</span><button class="button" on:click={load} disabled={loading||refreshing} aria-label="Refresh fleet data">{refreshing?'Refreshing…':'↻ Refresh'}</button></div></div>

{#if loading}<StatePanel state="loading" title="Reading fleet state…" message="Loading inventory and the latest system frames." />
{:else if error}<StatePanel state="error" message={error} retry={load} />
{:else if !summary || hosts.length === 0}<StatePanel state="empty" title="No agents enrolled" message="Enroll an agent to begin recording hosts, processes and system telemetry." />
{:else}
  <section class="kpi-strip panel" aria-label="Fleet inventory summary"><div class="kpi-primary"><span class="eyebrow">RECORDER HEALTH</span><strong class:attention={summary.offline > 0 || summary.degraded > 0}>{summary.offline > 0 ? 'ACTION NEEDED' : summary.degraded > 0 ? 'CHECK SIGNALS' : 'ALL SYSTEMS NOMINAL'}</strong><span class="subtle">{summary.healthy} healthy · {summary.degraded} degraded · {summary.offline} offline</span></div><div class="kpi"><span class="eyebrow">AGENTS</span><b>{hosts.length}</b><span class="subtle">registered installations</span></div><div class="kpi"><span class="eyebrow">SERVICES</span><b>{allEntities.filter(item => item.kind === 'service' && item.active).length}</b><span class="subtle">active now</span></div><div class="kpi"><span class="eyebrow">PROCESSES</span><b>{allEntities.filter(item => item.kind === 'process' && item.active).length}</b><span class="subtle">active · {summary.processes} recorded</span></div><div class="kpi"><span class="eyebrow">CONTAINERS</span><b>{allEntities.filter(item => item.kind === 'container' && item.active).length}</b><span class="subtle">active · {summary.containers} recorded</span></div><div class="kpi"><span class="eyebrow">DEPENDENCIES</span><b>{summary.dependencies}</b><span class="subtle">linked resources</span></div><div class="kpi"><span class="eyebrow">INGESTION DELAY</span><b class:attention={summary.ingestion_delay_ms > 5000}>{formatMetric(summary.ingestion_delay_ms / 1000, 'seconds')}</b><span class="subtle">event → recorder</span></div></section>

  <nav class="dashboard-tabs" aria-label="Agent dashboard views"><a href="/?view=overview" data-sveltekit-reload class:active={view==='overview'}>Overview</a><a href="/?view=system" data-sveltekit-reload class:active={view==='system'}>System metrics</a><a href="/?view=topology" data-sveltekit-reload class:active={view==='topology'}>Resource topology</a></nav>

  {#if view==='overview'}
  <section class="section-heading"><div><span class="eyebrow">Fleet / ranked by activity</span><h2>Top nodes</h2></div><span class="section-meta mono">SHOWING {topNodes.length} OF {hosts.length} REAL NODES</span></section>
  <section class="inventory panel" aria-label="Top nodes and their agents"><div class="table-head"><span>Node / agent</span><span>State</span><span>Services</span><span>Processes</span><span>Dependencies</span><span>Last frame</span></div>
    {#each topNodes as host}{@const report = reportFor(host)}<a class="inventory-row" class:selected={selectedHost?.id === host.id} href={`/?host=${encodeURIComponent(host.id)}`} on:click|preventDefault={() => setHost(host.id)}><div class="identity"><span class="agent-dot" class:offline={host.health === 'offline'} aria-hidden="true"></span><div><strong>{host.name}</strong><span class="mono">AGENT {host.agent_id?.slice(0, 12) || 'UNRESOLVED'}{testAgent(host) ? ' · TEST' : ''}</span></div>{#if testAgent(host)}<span class="tag">TEST</span>{/if}</div><div class="state-cell"><StatusMark status={host.health} /><span class="agent-version">{report?.agent_version || 'version unavailable'}</span></div><span class="count">{activeCount(hostServices(host))}</span><span class="count">{activeCount(hostProcesses(host))}</span><span class="count">{activeCount(hostDependencies(host))}</span><span class="last-frame mono" class:stale={isStale(host.last_seen)}>{isStale(host.last_seen) ? 'STALE · ' : ''}{formatTime(host.last_seen)}</span></a>{/each}
  </section>
  {#if selectedHost}<section class="section-heading"><div><span class="eyebrow">Service layer / {selectedHost.name}</span><h2>Services on this node</h2></div><a class="quiet-link" href="/?view=topology">Explore full topology →</a></section><section class="service-overview">{#each hostServices(selectedHost).filter(item => item.active) as service}<a class="service-summary panel" href={`/service/${service.id}`}><div><StatusMark status={service.health}/><span class="eyebrow">SERVICE</span></div><h3>{service.name}</h3><p>{activeCount(serviceProcesses(service))} live process · {serviceDependencies(service).length} dependencies</p><span>Open service telemetry →</span></a>{/each}</section>{/if}
  {/if}

  {#if view==='overview'||view==='system'}
  <section class="section-heading telemetry-heading"><div><span class="eyebrow">System telemetry / {selectedHost?.name}</span><h2>Host signals</h2><p>Curated system streams for the selected host. Values appear only when samples exist.</p></div><span class="range-label mono">{formatTime(chartRange.start)} — {formatTime(chartRange.end)}</span></section>
  {#if selectedHost && selectedMetrics.length}
    <section class="signal-grid" aria-label={`System telemetry for ${selectedHost.name}`}><article class="signal-card panel"><div class="signal-title"><div><span class="eyebrow">CPU</span><h3>Utilization</h3></div><strong class="metric-value">{formatMetric(metricValue(selectedMetrics, 'system.cpu.utilization'), 'percent')}</strong></div>{#if selectedGroups.cpu[0]}<MetricChart series={selectedGroups.cpu.find(item => item.name === 'system.cpu.utilization') || selectedGroups.cpu[0]} height={240}/>{/if}<span class="signal-note">load {formatMetric(metricValue(selectedMetrics, 'system.load1'), '')} / 1m · {formatMetric(metricValue(selectedMetrics, 'system.load5'), '')} / 5m</span></article><article class="signal-card panel"><div class="signal-title"><div><span class="eyebrow">MEMORY / RAM</span><h3>Available capacity</h3></div><strong class="metric-value">{bytes(metricValue(selectedMetrics, 'system.memory.available'))}</strong></div>{#if selectedGroups.memory[0]}<MetricChart series={selectedGroups.memory.find(item => item.name === 'system.memory.available') || selectedGroups.memory[0]} height={240}/>{/if}<span class="signal-note">of {bytes(metricValue(selectedMetrics, 'system.memory.total'))} total</span></article><article class="signal-card panel"><div class="signal-title"><div><span class="eyebrow">NETWORK</span><h3>Traffic</h3></div><strong class="metric-value">{rate(metricValue(selectedMetrics, 'system.network.rx_bytes.rate', 'sum'))}</strong></div>{#if selectedGroups.network[0]}<MetricChart series={selectedGroups.network.find(item => item.name === 'system.network.rx_bytes.rate') || selectedGroups.network[0]} height={240}/>{/if}<span class="signal-note">in · {rate(metricValue(selectedMetrics, 'system.network.tx_bytes.rate', 'sum'))} out</span></article><article class="signal-card panel"><div class="signal-title"><div><span class="eyebrow">DISK I/O</span><h3>Read / write throughput</h3></div><strong class="metric-value">{rate(metricValue(selectedMetrics, 'system.disk.sectors_read.rate', 'sum') == null ? null : (metricValue(selectedMetrics, 'system.disk.sectors_read.rate', 'sum') || 0) * 512)}</strong></div>{#if selectedGroups.disk[0]}<MetricChart series={selectedGroups.disk.find(item => item.name === 'system.disk.sectors_read.rate') || selectedGroups.disk[0]} height={240}/>{/if}<span class="signal-note">read · {rate(metricValue(selectedMetrics, 'system.disk.sectors_written.rate', 'sum') == null ? null : (metricValue(selectedMetrics, 'system.disk.sectors_written.rate', 'sum') || 0) * 512)} write</span></article></section>
    {#if view==='system'}<section class="system-detail panel"><header><div><span class="eyebrow">Signal catalog / selected host</span><h3>System-level streams</h3></div><span class="mono subtle">{selectedMetrics.length} representative series · {catalog.filter(item => item.name.startsWith('system.')).length} definitions</span></header><div class="stream-list">{#each selectedMetrics as metric}<div><span class="stream-name">{metric.name}</span><span class="chip">{metric.attributes && Object.values(metric.attributes).length ? Object.values(metric.attributes).join(' / ') : 'aggregate'}</span><strong class="mono">{formatMetric(metric.buckets.at(-1)?.last, metric.unit === 'By' ? 'bytes' : metric.unit)}</strong></div>{/each}</div></section>{/if}
  {:else}<StatePanel state="empty" title="No system samples in this range" message="Inventory is present, but this host has not reported system metrics for the selected window." />{/if}
  {/if}

  {#if view==='topology'}
  <section class="section-heading lower-heading"><div><span class="eyebrow">Resource map / selected host</span><h2>What this host runs</h2></div><a class="quiet-link" href="/timeline">Open unified timeline →</a></section>
  {#if selectedHost}<section class="node-map panel" aria-label={`Resource nodes on ${selectedHost.name}`}>
    <header class="node-root"><div class="node-icon">A</div><div><span class="eyebrow">AGENT</span><h3 class="mono">{selectedHost.agent_id?.slice(0, 12) || 'unresolved'}</h3></div><div class="host-branch"><span>HOST</span><strong>{selectedHost.name}</strong></div><div class="node-counts mono"><span>{activeCount(hostServices(selectedHost))} services</span><span>{activeCount(hostProcesses(selectedHost))} processes</span><span>{activeCount(hostContainers(selectedHost))} containers</span><span>{activeCount(hostDependencies(selectedHost))} dependencies</span></div></header>
    <div class="resource-toolbar"><label><span class="sr-only">Filter resources</span><input bind:value={resourceQuery} placeholder="Filter processes, services, PID…" /></label><button class:active={showHistorical} on:click={() => showHistorical = !showHistorical}>{showHistorical ? 'Showing history' : 'Live resources'} · {showHistorical ? 'hide inactive' : 'show all recorded'}</button></div>
    <div class="node-groups">
      <div class="node-column"><div class="column-title"><span>Services</span><b>{visibleResources(hostServices(selectedHost)).length} visible</b></div>{#each visibleResources(hostServices(selectedHost)) as service}<article class="service-node"><a class="service-title" href={`/service/${service.id}`}><StatusMark status={service.health}/><strong>{service.name}</strong><span>Inspect →</span></a><div class="child-list">{#each visibleResources(serviceProcesses(service)) as process}<a href={`/process/${process.id}`}><span class="branch">└</span><span>{process.name}</span><small class="mono">PID {process.pid || '—'}</small></a>{/each}{#if visibleResources(serviceProcesses(service)).length===0}<span class="empty-child">No matched live process</span>{/if}</div>{#if serviceDependencies(service).length}<div class="service-links"><span>USES</span>{#each serviceDependencies(service) as dependency}<a href={`/dependency/${dependency.id}`}>{dependency.name}</a>{/each}</div>{/if}</article>{/each}</div>
      <div class="node-column"><div class="column-title"><span>Processes</span><b>{visibleResources(unassignedProcesses(selectedHost)).length} visible</b></div><p class="column-note">Host processes not assigned to a configured service.</p><div class="flat-nodes">{#each visibleResources(unassignedProcesses(selectedHost)) as process}<a href={`/process/${process.id}`}><StatusMark status={process.health}/><span><strong>{process.name}</strong><small class="command">{process.command || 'command unavailable'}</small></span><small class="mono">PID {process.pid || '—'}</small></a>{/each}</div></div>
      <div class="node-column"><div class="resource-section"><div class="column-title"><span>Containers</span><b>{visibleResources(hostContainers(selectedHost)).length} visible</b></div><div class="flat-nodes">{#each visibleResources(hostContainers(selectedHost)) as container}<a href={`/container/${container.id}`}><StatusMark status={container.health}/><span>{container.name}</span><small>container</small></a>{/each}</div></div><div class="resource-section"><div class="column-title"><span>Dependencies</span><b>{visibleResources(hostDependencies(selectedHost)).length} visible</b></div><div class="flat-nodes">{#each visibleResources(hostDependencies(selectedHost)) as dependency}<a href={`/dependency/${dependency.id}`}><StatusMark status={dependency.health}/><span>{dependency.name}</span><small>dependency</small></a>{/each}</div></div></div>
    </div>
  </section>{/if}
  {/if}
{/if}

<style>
  .dashboard-tabs{display:flex;gap:4px;margin:-16px 0 28px;padding:4px;width:max-content;border:1px solid var(--border);border-radius:8px;background:var(--card)}.dashboard-tabs a{padding:8px 13px;border-radius:5px;color:var(--muted-foreground);font-size:12px;font-weight:600;text-decoration:none}.dashboard-tabs a:hover{color:var(--foreground);background:var(--secondary)}.dashboard-tabs a.active{color:var(--primary-foreground);background:var(--primary)}
  .page-heading,.section-heading,.signal-title,.system-detail header,.inventory-row,.table-head,.resource-card header,.heading-actions{display:flex;align-items:center;justify-content:space-between}.page-heading{align-items:flex-end;margin-bottom:24px}.page-heading h1{font-size:40px;line-height:1;margin:8px 0}.page-heading p,.telemetry-heading p{margin:0;color:var(--muted);font-size:13px}.heading-actions{gap:16px}.freshness,.range-label,.section-meta{font-size:10px;color:#81909e;letter-spacing:.06em}.kpi-strip{display:grid;grid-template-columns:1.55fr repeat(5,1fr);margin-bottom:32px}.kpi-strip>div{padding:20px;border-right:1px solid var(--line);min-width:0}.kpi-strip>div:last-child{border:0}.kpi-primary{display:flex;flex-direction:column;gap:6px}.kpi-primary strong{color:var(--cyan);font:600 20px 'Barlow Condensed';letter-spacing:.06em}.kpi-primary strong.attention,.attention{color:var(--amber)}.kpi b{display:block;margin:6px 0 2px;font:600 28px 'Barlow Condensed';color:var(--frost)}.section-heading{margin:0 0 12px}.section-heading h2{font:600 24px 'Barlow Condensed';margin:6px 0 0;letter-spacing:.03em}.inventory{overflow:hidden;margin-bottom:32px}.table-head,.inventory-row{display:grid;grid-template-columns:minmax(250px,2.2fr) minmax(150px,1.25fr) .6fr .65fr .85fr 135px;gap:16px;padding:14px 20px}.table-head{font:10px 'IBM Plex Mono';letter-spacing:.1em;text-transform:uppercase;color:#8493a0;background:#0d151d;border-bottom:1px solid var(--line)}.inventory-row{justify-content:initial;color:var(--frost);text-decoration:none;border-bottom:1px solid rgba(48,54,61,.7);transition:background .15s}.inventory-row:last-child{border-bottom:0}.inventory-row:hover,.inventory-row.selected{background:#17232e}.identity{display:flex;align-items:center;gap:10px;min-width:0}.identity>div{display:flex;flex-direction:column;min-width:0}.identity strong{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.identity .mono{font-size:9px;color:#80909f;margin-top:4px}.a