nter;border-radius:7px;background:var(--brand-500);color:#111;font-weight:700}.node-counts{margin-left:auto;display:flex;gap:14px;color:#91a0ad;font-size:10px}.node-groups{display:grid;grid-template-columns:1.25fr 1fr 1fr}.node-column{min-width:0;padding:16px;border-right:1px solid var(--line)}.node-column:last-child{border:0}.column-title{display:flex;justify-content:space-between;margin-bottom:12px;color:#98a6b3;font-size:11px}.column-title b{font:12px 'IBM Plex Mono';color:var(--frost)}.service-node{border:1px solid var(--line);border-radius:6px;margin-bottom:10px;background:#0c1116}.service-title,.child-list a,.flat-nodes a,.static-node{display:grid;align-items:center;gap:8px;color:var(--frost);text-decoration:none}.service-title{grid-template-columns:74px minmax(0,1fr) auto;padding:10px}.service-title>span:last-child{font-size:10px;color:var(--brand-300)}.child-list{border-top:1px solid var(--line);padding:5px 10px 8px}.child-list a{grid-template-columns:14px minmax(0,1fr) auto;padding:5px 0;font-size:11px}.branch{color:#52606d}.child-list small,.flat-nodes small{color:#738391;font-size:9px}.flat-nodes a,.static-node{grid-template-columns:74px minmax(0,1fr) auto;padding:9px 0;border-bottom:1px solid rgba(48,54,61,.55);font-size:11px}.static-node small{color:#738391}.empty-child,.more-child{display:block;padding:5px 0;color:#6f7f8d;font-size:10px}.more-child{font-family:'IBM Plex Mono'}.resource-card{padding:16px;min-width:0}@media(max-width:1100px){.kpi-strip{grid-template-columns:repeat(3,1fr)}.kpi-primary{grid-column:span 3}.signal-grid{grid-template-columns:repeat(2,1fr)}.node-groups{grid-template-columns:1fr}.node-column{border-right:0;border-bottom:1px solid var(--line)}.table-head,.inventory-row{grid-template-columns:minmax(220px,2fr) minmax(130px,1.1fr) .5fr .6fr .8fr 115px;gap:10px;padding-left:14px;padding-right:14px}}@media(max-width:760px){.page-heading{align-items:flex-start;gap:16px}.page-heading h1{font-size:34px}.heading-actions{align-items:flex-